import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.BrSBneze.js";const m=JSON.parse('{"title":"Print the parts","description":"","frontmatter":{},"headers":[],"relativePath":"hardware/printing.md","filePath":"hardware/printing.md","lastUpdated":1788882780000}'),i={name:"hardware/printing.md"};function o(n,t,l,s,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="print-the-parts" tabindex="-1">Print the parts <a class="header-anchor" href="#print-the-parts" aria-label="Permalink to &quot;Print the parts&quot;">​</a></h1><p>The printable files are stored in the <a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/STL" target="_blank" rel="noreferrer"><code>STL/</code> directory</a>. Editable sources are available separately in <a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/CAD" target="_blank" rel="noreferrer"><code>CAD/</code></a>.</p><div class="tip custom-block"><p class="custom-block-title">Check the fit first</p><p>Before printing the full set, print one honeycomb cell and one attachment base. Verify that the attachment seats fully, remains stable during manipulation, and can be removed without damaging either part.</p></div><h2 id="printer-requirements" tabindex="-1">Printer requirements <a class="header-anchor" href="#printer-requirements" aria-label="Permalink to &quot;Printer requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Recommendation</th></tr></thead><tbody><tr><td>Process</td><td>Consumer-grade FDM</td></tr><tr><td>Material</td><td>PLA, 1.75 mm</td></tr><tr><td>Minimum build area</td><td>300 × 300 mm for the complete base</td></tr><tr><td>Nozzle</td><td>0.4 mm</td></tr><tr><td>Layer height</td><td>0.20 mm</td></tr><tr><td>Wall count</td><td>4</td></tr><tr><td>Top / bottom layers</td><td>5 / 5</td></tr><tr><td>Print speed</td><td>50 mm/s</td></tr><tr><td>Nozzle temperature</td><td>200–220 °C</td></tr><tr><td>Bed temperature</td><td>50–60 °C</td></tr><tr><td>Cooling</td><td>100%</td></tr><tr><td>Adhesion</td><td>Skirt or brim</td></tr><tr><td>Supports</td><td>Only where required</td></tr></tbody></table><p>Smaller variants of the honeycomb panel are included in the repository, but the full benchmark geometry is designed around a 300 × 300 mm build area.</p><h2 id="infill-by-part-type" tabindex="-1">Infill by part type <a class="header-anchor" href="#infill-by-part-type" aria-label="Permalink to &quot;Infill by part type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part type</th><th style="text-align:right;">Infill</th></tr></thead><tbody><tr><td>Base structure</td><td style="text-align:right;">20%</td></tr><tr><td>Mechanical parts</td><td style="text-align:right;">25%</td></tr><tr><td>Torque components</td><td style="text-align:right;">30%</td></tr><tr><td>Threads</td><td style="text-align:right;">25%</td></tr><tr><td>Decorative covers</td><td style="text-align:right;">15%</td></tr></tbody></table><h2 id="orientation" tabindex="-1">Orientation <a class="header-anchor" href="#orientation" aria-label="Permalink to &quot;Orientation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Orientation</th></tr></thead><tbody><tr><td>Threads and screws</td><td>Vertical</td></tr><tr><td>Nuts</td><td>Flat</td></tr><tr><td>Valves</td><td>Handle up</td></tr><tr><td>Drawer</td><td>Largest face on the bed</td></tr><tr><td>Pegs</td><td>Vertical</td></tr><tr><td>Shock absorber parts</td><td>Sideways</td></tr></tbody></table><h2 id="print-order" tabindex="-1">Print order <a class="header-anchor" href="#print-order" aria-label="Permalink to &quot;Print order&quot;">​</a></h2><p>For a new printer or filament batch, use this order:</p><ol><li>Print one honeycomb cell and one simple module base.</li><li>Check the press fit and dimensional consistency.</li><li>Print the M8 and M30 test pieces before the complete threaded modules.</li><li>Print the base panels.</li><li>Print the remaining functional mechanisms.</li></ol><p>This order catches tolerance and thread problems before the longest prints.</p><h2 id="post-processing" tabindex="-1">Post-processing <a class="header-anchor" href="#post-processing" aria-label="Permalink to &quot;Post-processing&quot;">​</a></h2><ul><li>Remove stringing and support material without rounding functional edges.</li><li>Check that mating faces seat fully.</li><li>Test threads by hand before mounting the module.</li><li>Apply light sanding only when printer calibration produces tight surfaces.</li><li>Record any sanding or dimensional adjustment in the trial notes.</li></ul><p>Do not lubricate or modify friction surfaces without reporting the change. These changes can alter the task difficulty.</p><h2 id="files-to-download" tabindex="-1">Files to download <a class="header-anchor" href="#files-to-download" aria-label="Permalink to &quot;Files to download&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Repository folder</th></tr></thead><tbody><tr><td>Honeycomb base</td><td><a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/STL/Honeycomb" target="_blank" rel="noreferrer"><code>STL/Honeycomb</code></a></td></tr><tr><td>Valves</td><td><a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/STL/Valves" target="_blank" rel="noreferrer"><code>STL/Valves</code></a></td></tr><tr><td>Threads</td><td><a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/STL/Threads" target="_blank" rel="noreferrer"><code>STL/Threads</code></a></td></tr><tr><td>Other mechanisms</td><td><a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/STL" target="_blank" rel="noreferrer"><code>STL/</code></a></td></tr></tbody></table><p>The repository README also links to the current module-specific printing guide.</p>',20)])])}const b=e(i,[["render",o]]);export{m as __pageData,b as default};
